def header(active="", spanish=False):
    if spanish:
        links = [("Soluciones", "es.html#soluciones"), ("Reparación Salesforce", "reparacion-salesforce.html"), ("English", "index.html")]
        cta = "Hablemos de tu proyecto"
        nav = "Navegación principal"
    else:
        links = [("Problems & solutions", "solutions.html"), ("Salesforce repair", "salesforce-repair.html"), ("For partners", "contracts.html"), ("Español", "es.html")]
        cta = "Discuss a project"
        nav = "Main navigation"
    items = "".join(f'<a href="{href}"' + (' aria-current="page"' if href == active else '') + f'>{name}</a>' for name, href in links)
    return f'<a class="skip" href="#main">{"Saltar al contenido" if spanish else "Skip to content"}</a><header class="site-header"><nav class="nav-shell" aria-label="{nav}"><a class="brand" href="index.html" aria-label="KS Tech Consulting home"><img src="img/logo1.png" alt="KS Tech Consulting"></a><button class="menu-toggle" type="button" data-menu-toggle aria-expanded="false" aria-controls="nav-links">Menu</button><div class="nav-links" id="nav-links" data-nav-links>{items}<a class="nav-cta" href="{("es.html#diagnostico" if spanish else "start.html")}">{cta}</a></div></nav></header>'


