def page(title, description, filename, body, active="", spanish=False, schema=None):
    counterpart = 'salesforce-repair.html' if filename == 'reparacion-salesforce.html' else ('reparacion-salesforce.html' if filename == 'salesforce-repair.html' else ('index.html' if spanish else 'es.html'))
    alternate = '<link rel="alternate" hreflang="' + ('en' if spanish else 'es') + '" href="' + DOMAIN + counterpart + '">'
    schema_tag = '<script type="application/ld+json">' + json.dumps(schema, ensure_ascii=False) + '</script>' if schema else ''
    html = f'''<!doctype html><html lang="{"es" if spanish else "en"}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{escape(title)}</title><meta name="description" content="{escape(description, quote=True)}"><link rel="canonical" href="{DOMAIN + filename}">{alternate}<link rel="icon" href="img/favicon-brand.svg" type="image/svg+xml"><link rel="stylesheet" href="css/v2.css"><script defer src="js/v2.js"></script>{schema_tag}</head><body>{header(active, spanish)}<main id="main">{body}</main>{footer(spanish)}</body></html>'''
    (ROOT / filename).write_text(html, encoding="utf-8")


