def detail(d):
    symptoms = ''.join(f'<li>{escape(x)}</li>' for x in d['symptoms'])
    work = ''.join(f'<li>{escape(x)}</li>' for x in d['work'])
    faqs = ''.join(f'<details><summary>{escape(q)}</summary><p>{escape(a)}</p></details>' for q, a in d['faq'])
    body = f'''<section class="page-hero"><div class="container"><p class="breadcrumb"><a href="index.html">Home</a> / <a href="solutions.html">Solutions</a> / {escape(d['eyebrow'])}</p><p class="eyebrow light">{escape(d['eyebrow'])}</p><h1>{escape(d['heading'])}</h1><p>{escape(d['lead'])}</p><a class="button primary" href="start.html?issue={d['issue']}">Discuss this problem</a></div></section><section class="section white"><div class="container detail-grid"><div><h2>Does this sound familiar?</h2><ul>{symptoms}</ul><h3>How we approach it</h3><ol>{work}</ol><h3>A useful first deliverable</h3><p>{escape(d['deliver'])}</p><p class="notice">We confirm scope, access, timing and fees before implementation. No results are guaranteed by these illustrative scenarios.</p></div><aside class="aside-card"><p class="eyebrow">For the first conversation</p><h3>Bring what you already know.</h3><p>{escape(d['bring'])}</p><p>Please do not include credentials, API keys or customer records in the inquiry.</p><a class="button dark" href="start.html?issue={d['issue']}">Request a project conversation</a></aside></div></section><section class="section"><div class="container faq"><p class="eyebrow">Common questions</p><h2>Before we start</h2>{faqs}</div></section><section class="cta-band"><div class="container split"><div><h2>Turn the problem into a defined next step.</h2><p>Share a short description and we will discuss whether a focused project fits.</p></div><a class="button dark" href="start.html?issue={d['issue']}">Talk to our team</a></div></section>'''
    schema = {"@context": "https://schema.org", "@type": "FAQPage", "mainEntity": [{"@type": "Question", "name": q, "acceptedAnswer": {"@type": "Answer", "text": a}} for q, a in d['faq']]}
    page(d['title'], d['description'], d['file'], body, 'salesforce-repair.html' if d['issue'] == 'salesforce' else '', schema=schema)


